if isServer() then
    return
end

-- ---------------------------------------------------------------------------
-- Project Viewpoint (workshop 3809306528) draws the world in 3D and has no
-- idea what the garage's taxi is: phuninteriors_02_* are in none of its
-- vanilla tables and have no tile geometry, so the taxi was simply not there.
--
-- A Viewpoint model pack binds a sprite to an OBJ. Ours binds vanilla's own
-- CarTaxi, wheels and skin, to the middle west square of the ten the taxi
-- stands on, and leaves the other nine alone. It is generated by
-- Art/taxi/make_taxi.py into media/viewpoint/; nothing in it is drawn by
-- anything but Viewpoint, so the iso view is unaffected. The shells around
-- the garage are PhunInteriors' tiles and its own pack covers them.
--
-- A soft hook, as PhunInteriors' client_viewpoint.lua is:
-- Viewpoint.ModelPacks only exists while Viewpoint's Java is loaded.
-- Registered on boot and again on game start, because the Java side may not
-- be up when this file first runs, and a repeat is harmless.
-- ---------------------------------------------------------------------------

local MANIFEST = "media/viewpoint/phuntaxi.properties"

-- The test build ships under its own id; ModelPacks resolves the manifest
-- against the folder of the mod it is named for.
local function ourModId()
    if getActivatedMods():contains("phuntaxitest") then
        return "phuntaxitest"
    end
    return "phuntaxi"
end

local registered = false

local function register()
    if registered or not Viewpoint or not Viewpoint.ModelPacks then
        return
    end
    local ok, result = pcall(Viewpoint.ModelPacks.register, ourModId(), MANIFEST)
    if not ok then
        print("[PhunTaxi] Viewpoint model pack: " .. tostring(result))
        return
    end
    if result then
        registered = true
        print("[PhunTaxi] registered the Viewpoint model pack")
    end
end

Events.OnGameBoot.Add(register)
Events.OnGameStart.Add(register)
register()
